/* 世志搞事 — maps (PLAN.md §9). Generated by code, not hand-written ASCII.
 * Letters: '.' air, 'S' spawn (stands on the cell below), 'F' flag; every other letter is solid and picks a look in gaoshi.js. */
'use strict';
var GaoshiMaps = (function(){
  function grid(W, H){
    const g = Array.from({length:H}, ()=>Array(W).fill('.'));
    const fill = (x0,y0,x1,y1,c='#')=>{ for (let y=y0;y<=y1;y++) for (let x=x0;x<=x1;x++) g[y][x] = c; };
    return {g, fill};
  }
  function buildRooftops(){
    const W = 32, H = 18, {g, fill} = grid(W, H);
    fill(0,10,6,17,'#');           // left tower (start), top row 10
    fill(7,13,8,13,'#');           // ledge sticking out of the start tower
    fill(21,8,31,17,'#');          // right tower (goal), 2 higher
    fill(26,5,27,7,'C');           // chimney
    g[7][29] = 'F';
    [1,2,4,5].forEach(x=>g[9][x]='S');
    return { id:'rooftops', name:'屋頂', size:[W,H], grid:g.map(r=>r.join('')),
      goal:{x:28.5, y:4, w:2, h:4}, hazards:[], noPlaceZones:[], killY:20, solidBounds:true,
      sky:[0x2b3a66, 0xe8946a], look:'city',
      // 第 1 次試玩用的測試橋；第 2 次有放道具後拿掉
      testBoxes:[{x:10,y:10,w:3,h:1},{x:15,y:9,w:3,h:1}] };
  }
  function buildFarm(){
    const W = 32, H = 18, {g, fill} = grid(W, H);
    fill(0,16,31,17,'G');          // ground (no pit)
    fill(0,8,7,15,'B');            // barn, roof top row 8 (start)
    fill(9,13,12,15,'T');          // tractor
    fill(18,12,22,15,'M');         // thresher body
    fill(23,9,24,15,'P');          // step pillar
    fill(25,5,29,15,'O');          // silo (goal on top)
    g[4][27] = 'F';
    [1,2,4,5].forEach(x=>g[7][x]='S');
    return { id:'farm', name:'農場', size:[W,H], grid:g.map(r=>r.join('')),
      goal:{x:26.5, y:1, w:2, h:4},
      hazards:[{type:'rotating_blade', center:[16.5,13], length:4, thickness:0.4, periodSec:3.0, lethal:true}],   // TODO(verify): 對照原作 period
      noPlaceZones:[{x:0,y:8,w:8,h:8}], hideZones:[{x:0,y:15,w:32,h:1}], killY:99, solidBounds:true,
      sky:[0x5d9ad6, 0xf3d9a0], look:'farm', testBoxes:[] };
  }
  const LIST = [buildRooftops(), buildFarm()];
  return { LIST, byId:Object.fromEntries(LIST.map(m=>[m.id,m])) };
})();
if (typeof module !== 'undefined') module.exports = GaoshiMaps;
